function briefing(id){const c=person(id);if(!c)return;const notes=c.notes.slice().reverse().sort((a,b)=>b.date.localeCompare(a.date)),tasks=tasksFor(id),deals=db.deals.filter(d=>d.contact===id&&['Anfrage','Angebot offen'].includes(d.status));openModal(`<span class="eyebrow">DEINE GESPRÄCHSVORBEREITUNG</span><div class="deal-top">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${esc(c.company)}</p></div></div><p class="notice">Zusammengestellt aus deinen gespeicherten Einträgen. Keine KI-Zusammenfassung.</p><h2>Zuletzt besprochen</h2>${notes[0]?`<article class="brief-note"><p>${esc(notes[0].text)}</p><span class="sub">Notiz vom ${esc(notes[0].date)}</span></article>`:'<p class="muted">Noch keine Gesprächsnotiz vorhanden.</p>'}<h2>Das ist noch offen</h2>${tasks.map(t=>`<div class="row"><span>${esc(t.title)}</span>${badge(t.date)}</div>`).join('')||'<p class="muted">Keine offenen Zusagen erfasst.</p>'}<h2>Gemeinsame Möglichkeiten</h2>${deals.map(d=>`<button class="row" onclick="dealForm('${d.id}')"><span class="body"><h3>${esc(d.title)}</h3><span class="sub">${esc(d.status)}</span></span><b>${money(d.amount)}</b></button>`).join('')||'<p class="muted">Keine offenen Chancen erfasst.</p>'}<div class="actions"><button class="primary" onclick="capture('${id}')">${svg('mic')}Gespräch festhalten</button><div class="actions"><button class="secondary" onclick="detail('${id}')">Kontakt öffnen</button><button class="text-button" onclick="locationResolve('${id}')">Standort prüfen</button></div></div>`,{wide:true})}
function taskRow(t){const c=person(t.contact);return `<div class="row"><button onclick="detail('${t.contact}')" aria-label="${esc(c?.name)} öffnen" style="padding:0">${avatar(c)}</button><div class="body"><h3>${esc(c?.name||'Kontakt')}</h3><p>${esc(t.title)}</p></div>${badge(t.date)}<button class="check ${t.done?'done':''}" aria-label="${t.done?'Wieder öffnen':'Erledigen'}: ${esc(t.title)}" onclick="toggleTask('${t.id}')">${t.done?'✓':''}</button></div>`}
