function tasksView(){return `${heading('Ein Schritt<br><span class="underline">nach dem anderen.</span>')}<button class="primary" onclick="taskForm()">${svg('plus')}Aufgabe</button><h2 style="margin-top:24px">Offen</h2>${db.tasks.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)).map(taskRow).join('')||'<p class="notice">Keine offenen Aufgaben.</p>'}<details style="margin-top:24px"><summary>Erledigt (${db.tasks.filter(t=>t.done).length})</summary>${db.tasks.filter(t=>t.done).map(taskRow).join('')}</details><p class="notice">Erinnerungen erscheinen in der App. Push- und E-Mail-Benachrichtigungen sind noch nicht angebunden.</p>`}
function settings(){return `<div class="settings-layout">${heading('Ganz dein<br><span class="underline">Networkee.</span>',false)}<button class="profile-card warm-panel" style="width:100%;text-align:left" onclick="profileForm()">${avatar(db.profile)}<span><h3>${esc(db.profile.name||'Dein Name')}</h3><span class="sub">${esc(db.profile.company||'Dein persönlicher Arbeitsplatz')}</span></span></button><h2>Deine Akzentfarbe</h2><div class="swatches warm-panel">${Object.keys(themes).map(n=>`<button aria-pressed="${(db.theme||'Blau')===n}" onclick="change(()=>db.theme='${n}')"><span class="swatch" style="background:${themes[n][0]}">${(db.theme||'Blau')===n?'✓':''}</span>${n}</button>`).join('')}</div><h2>Dein Assistent</h2><div class="setting-row">${mascot()}<span>Animationen</span><button role="switch" aria-checked="${db.animations}" aria-label="Animationen" class="toggle ${db.animations?'on':''}" onclick="change(()=>db.animations=!db.animations)"></button></div>${[['Kontakte','Profil & Konto','profileForm()'],['bell','Erinnerungen',"go('Aufgaben')"],['shield','Daten & Privatsphäre','privacy()'],['help','Hilfe & Feedback','help()']].map(([i,t,a])=>`<button class="setting-row" onclick="${a}">${svg(i)}<span>${t}</span>${svg('chevron')}</button>`).join('')}<p class="signature">Mehr Zeit für echte Beziehungen.</p></div>`}
function openModal(html,{wide=false,record=false}={}){if($('#modal').innerHTML&&!closeModal())return false;modalReturnFocus=document.activeElement;dirty=false;$('#modal').innerHTML=`<div class="modal"><section class="dialog ${wide?'wide':''} ${record?'record-screen':''}" role="dialog" aria-modal="true" aria-label="Networkee Dialog"><div class="dialog-toolbar"><span class="sub">${record?'Gespräch festhalten':'Dein Networkee'}</span><button class="icon-button" aria-label="Schliessen" onclick="closeModal()">${svg('close')}</button></div>${html}</section></div>`;document.body.classList.add('modal-open');$('#modal').querySelectorAll('label').forEach((label,i)=>{const field=label.nextElementSibling;if(!label.htmlFor&&field?.matches('input,select,textarea')){field.id=field.id||'modal-field-'+i;label.htmlFor=field.id}});$('#modal').oninput=()=>dirty=true;$('#modal').onchange=()=>dirty=true;setTimeout(()=>$('#modal input:not([type=file]),#modal textarea,#modal select,#modal button')?.focus(),50);return true}
function closeModal(force=false){if(!$('#modal').innerHTML)return true;if(!force&&(dirty||recording?.active||recording?.blob)&&!confirm('Nicht gespeicherte Eingaben und die Aufnahme verwerfen?'))return false;cleanupRecording();picker?.remove();picker=null;$('#modal').innerHTML='';document.body.classList.remove('modal-open');dirty=false;modalReturnFocus?.focus?.();return true}
const contactOptions=id=>db.contacts.map(c=>`<option value="${c.id}" ${c.id===id?'selected':''}>${esc(c.name)}</option>`).join('');
async function readPhoto(file){if(!file)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Bitte JPG, PNG oder WebP bis 5 MB wählen.');const bmp=await createImageBitmap(file);const c=document.createElement('canvas');const scale=Math.min(1,320/Math.max(bmp.width,bmp.height));c.width=Math.round(bmp.width*scale);c.height=Math.round(bmp.height*scale);c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);bmp.close();return c.toDataURL('image/jpeg',.8)}
async function photoChanged(input,target){try{const photo=await readPhoto(input.files[0]);input.dataset.photo=photo;$(target).innerHTML=avatar({name:'',photo});dirty=true}catch(e){toast(e.message);input.value=''}}
function profileForm(){const p=db.profile;if(!openModal(`<h1>Dein persönlicher<br><span class="underline">Arbeitsplatz.</span></h1><form id="pf"><label>Name</label><input name="name" value="${esc(p.name)}" maxlength="100" required><label>Unternehmen / Beschreibung</label><input name="company" value="${esc(p.company)}" maxlength="150"><label for="profilePhoto">Profilbild (optional)</label><input type="file" id="profilePhoto" accept="image/jpeg,image/png,image/webp" onchange="photoChanged(this,'#photoPreview')"><div class="photo-preview" id="photoPreview">${avatar(p)}</div><label><input style="width:auto" name="removePhoto" type="checkbox"> Bild entfernen</label><p class="notice">Dieses Profil wird nur lokal gespeichert. Registrierung und geräteübergreifende Anmeldung folgen später.</p><button class="primary full">Profil speichern</button></form>`))return;$('#pf').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);const name=f.get('name').trim();if(!name)return toast('Bitte einen Namen eingeben.');if(change(()=>db.profile={name,company:f.get('company').trim(),photo:f.get('removePhoto')?'':$('#profilePhoto').dataset.photo||p.photo||''},'Profil gespeichert'))closeModal(true)}}
function contactForm(id){const c=person(id)||{};if(!openModal(`<h1>${id?'Kontakt bearbeiten':'Ein neuer Kontakt.'}</h1><form id="cf"><label>Name</label><input name="name" required maxlength="120" value="${esc(c.name)}"><div class="twofields"><div><label>Unternehmen</label><input name="company" maxlength="150" value="${esc(c.company)}"></div><div><label>Typ</label><select name="type"><option ${c.type==='Interessent'?'selected':''}>Interessent</option><option ${c.type==='Kunde'?'selected':''}>Kunde</option></select></div></div><label>E-Mail</label><input name="email" type="email" value="${esc(c.email)}"><label>Telefon</label><input name="phone" type="tel" value="${esc(c.phone)}"><label>Kontaktfoto (optional)</label><input type="file" id="contactPhoto" accept="image/jpeg,image/png,image/webp" onchange="photoChanged(this,'#photoPreview')"><div class="photo-preview" id="photoPreview">${avatar(c)}</div><label><input style="width:auto" name="removePhoto" type="checkbox"> Foto entfernen</label><div class="twofields"><div><label>Ort</label><input oninput="locationTextChanged()" name="location" value="${esc(c.location)}" placeholder="Zürich"></div><div><label>Land</label><input oninput="locationTextChanged()" name="country" value="${esc(c.country)}" placeholder="Schweiz"></div></div><p class="sub">Ort und Land werden gespeichert. Anschliessend kannst du den passenden Kartenpunkt über die Ortssuche bestätigen.</p><button type="button" class="secondary full" onclick="pickLocation()">${svg('pin')} Standort auf Karte wählen</button><details style="margin-top:14px"><summary>Koordinaten bearbeiten</summary><div class="twofields"><div><label>Breitengrad</label><input name="lat" type="number" min="-90" max="90" step="any" value="${esc(c.lat??'')}"></div><div><label>Längengrad</label><input name="lng" type="number" min="-180" max="180" step="any" value="${esc(c.lng??'')}"></div></div><button type="button" class="text-button" onclick="$('#cf [name=lat]').value='';$('#cf [name=lng]').value='';dirty=true;$('#locationStatus').textContent='Markierung entfernt. Bitte speichern.'">Markierung entfernen</button></details><p class="sub" id="locationStatus">${located(c)?'Standort hinterlegt.':'Noch keine Kartenposition.'}</p><div id="picker"></div><button class="primary full">Kontakt speichern</button>${id?`<button type="button" class="text-button danger full" onclick="deleteContact('${id}')">Kontakt löschen</button>`:''}</form>`,{wide:true}))return;$('#cf').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.name.trim())return toast('Bitte einen Namen eingeben.');if((f.lat==='')!==(f.lng===''))return toast('Beide Koordinaten angeben oder beide leeren.');const v={name:f.name.trim(),company:f.company.trim(),email:f.email.trim(),phone:f.phone.trim(),type:f.type,location:f.location.trim(),country:f.country.trim(),lat:f.lat===''?'':+f.lat,lng:f.lng===''?'':+f.lng,photo:f.removePhoto?'':$('#contactPhoto').dataset.photo||c.photo||''};const key=id||uid();if(change(()=>{if(id)Object.assign(c,v);else db.contacts.push({...v,id:key,notes:[]})},'Kontakt gespeichert')){closeModal(true);if(v.location&&!located(v))locationResolve(key)}}}
function deleteContact(id){if(!confirm('Kontakt und seine Notizen, Aufgaben und Chancen endgültig aus diesem Browser löschen?'))return;if(change(()=>{db.contacts=db.contacts.filter(c=>c.id!==id);db.tasks=db.tasks.filter(t=>t.contact!==id);db.deals=db.deals.filter(d=>d.contact!==id)},'Kontakt gelöscht'))closeModal(true)}
function detail(id){const c=person(id);if(!c)return;openModal(`<div class="deal-top">${avatar(c)}<div><h1 style="margin:0">${esc(c.name)}</h1><p class="sub">${esc(c.company)} · ${esc(c.type)}</p></div></div><p class="muted">${esc(c.location||'Noch kein Standort')}${c.country?' · '+esc(c.country):''}</p><p>${esc(c.email)}${c.phone?' · '+esc(c.phone):''}</p><div class="actions"><button class="primary" onclick="capture('${id}')">${svg('mic')}Gespräch</button><button class="secondary" onclick="contactForm('${id}')">Bearbeiten</button></div><button class="secondary full" onclick="briefing('${id}')">Gespräch vorbereiten</button><h2 style="margin-top:25px">Offene Zusagen</h2>${tasksFor(id).map(t=>`<div class="row"><span class="body">${esc(t.title)}<br>${badge(t.date)}</span><button class="check" aria-label="Aufgabe erledigen" onclick="toggleTask('${t.id}');detail('${id}')"></button></div>`).join('')||'<p class="sub">Keine offenen Zusagen.</p>'}<button class="text-button" onclick="taskForm('${id}')">＋ Aufgabe</button><h2 style="margin-top:20px">Geschäftschancen</h2>${db.deals.filter(d=>d.contact===id).map(d=>`<button class="row" onclick="dealForm('${d.id}')"><span class="body"><h3>${esc(d.title)}</h3><span class="sub">${esc(d.status)}</span></span><b>${money(d.amount)}</b></button>`).join('')||'<p class="sub">Noch keine Chancen erfasst.</p>'}<button class="text-button" onclick="dealForm(null,'${id}')">＋ Chance</button><h2 style="margin-top:22px">Gesprächshistorie</h2>${c.notes.slice().reverse().map(n=>`<article class="note"><div class="sub">${esc(n.date)}</div><p>${esc(n.text)}</p></article>`).join('')||'<p class="sub">Das nächste Gespräch ist ein guter Anfang.</p>'}`,{wide:true})}
function taskForm(contact){if(!db.contacts.length){toast('Lege zuerst einen Kontakt an.');return contactForm()}if(!openModal(`<h1>Was ist der<br>nächste Schritt?</h1><form id="tf"><label>Kontakt</label><select name="contact">${contactOptions(contact)}</select><label>Aufgabe</label><input name="title" required maxlength="200" placeholder="Angebot besprechen"><label>Fällig am</label><input name="date" type="date" value="${today()}" required><button class="primary full">Aufgabe speichern</button></form>`))return;$('#tf').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.title.trim())return toast('Bitte eine Aufgabe eingeben.');if(change(()=>db.tasks.push({...v,title:v.title.trim(),id:uid(),done:false}),'Aufgabe gespeichert'))closeModal(true)}}
function dealForm(id,contact){if(!db.contacts.length){toast('Lege zuerst einen Kontakt an.');return contactForm()}const d=db.deals.find(x=>x.id===id)||{},task=id?db.tasks.find(t=>t.deal===id&&!t.done):undefined;if(!openModal(`<h1>${id?'Chance bearbeiten':'Eine neue Möglichkeit.'}</h1><form id="df"><label>Kontakt</label><select name="contact">${contactOptions(d.contact||contact)}</select><label>Projekt / Leistung</label><input name="title" required maxlength="150" value="${esc(d.title)}"><div class="twofields"><div><label>Wert in CHF</label><input name="amount" type="number" min="0" max="999999999" step="0.01" required value="${d.amount??0}"></div><div><label>Status</label><select name="status">${statuses.map(s=>`<option ${d.status===s?'selected':''}>${s}</option>`).join('')}</select></div></div><label>Nächster Schritt (optional)</label><input name="task" maxlength="200" value="${esc(task?.title||'')}"><label>Fällig am</label><input name="date" type="date" value="${task?.date||today()}"><button class="primary full">Chance speichern</button>${id?`<button type="button" class="text-button danger full" onclick="deleteDeal('${id}')">Chance löschen</button>`:''}</form>`))return;$('#df').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));if(!v.title.trim())return toast('Bitte eine Bezeichnung eingeben.');if(v.task.trim()&&!v.date)return toast('Bitte ein Datum für die Aufgabe wählen.');const key=id||uid();if(change(()=>{const vals={contact:v.contact,title:v.title.trim(),amount:Number(v.amount),status:v.status};if(id)Object.assign(d,vals);else db.deals.push({...vals,id:key});db.tasks.filter(t=>t.deal===key).forEach(t=>t.contact=v.contact);if(v.task.trim()){if(task)Object.assign(task,{title:v.task.trim(),date:v.date});else db.tasks.push({id:uid(),deal:key,contact:v.contact,title:v.task.trim(),date:v.date,done:false})}else if(task)db.tasks=db.tasks.filter(t=>t.id!==task.id)},'Chance gespeichert'))closeModal(true)}}
function deleteDeal(id){if(!confirm('Chance löschen? Zugehörige Aufgaben bleiben als Kontaktaufgaben erhalten.'))return;if(change(()=>{db.deals=db.deals.filter(d=>d.id!==id);db.tasks.filter(t=>t.deal===id).forEach(t=>delete t.deal)},'Chance gelöscht'))closeModal(true)}
function capture(contact){if(!db.contacts.length){toast('Lege zuerst einen Kontakt an.');return contactForm()}if(!openModal(`<h1>Ein Gedanke.<br><span class="underline">Schon festgehalten.</span></h1><label for="noteContact" style="text-align:left">Gespräch mit</label><select id="noteContact">${contactOptions(contact)}</select><div class="record-ring" id="recordRing">${mascot()}</div><canvas class="wave" id="wave" width="660" height="116" aria-label="Mikrofonpegel"></canvas><div class="record-status"><span id="recordDot"></span><span id="recordStatus" aria-live="polite">Bereit, wenn du es bist.</span><span id="recordTime" class="record-time">00:00</span></div><p class="record-help">Ein guter Gedanke verdient einen Platz.</p><button class="primary full" type="button" id="recordButton" onclick="recordToggle()">${svg('mic')}Aufnahme starten</button><div id="audioResult"></div><p class="notice">Audio wird lokal aufgenommen. Automatische Transkription und KI folgen später. Trage die Notiz vorerst als Text ein.</p><label style="text-align:left" for="noteText">Was möchtest du festhalten?</label><textarea id="noteText" maxlength="12000" placeholder="Wichtiges aus dem Gespräch und offene Zusagen …"></textarea><button class="primary full" onclick="reviewNote()">Notiz & nächsten Schritt prüfen</button><p class="sub">Du prüfst alles, bevor es gespeichert wird.</p>`,{record:true}))return;recording={active:false,blob:null,url:null,stream:null,recorder:null,ctx:null,raf:null,timer:null,pending:false,disposed:false};drawIdleWave()}
function drawIdleWave(){const canvas=$('#wave');if(!canvas)return;const c=canvas.getContext('2d');c.clearRect(0,0,660,116);c.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--soft');for(let i=0;i<38;i++){c.beginPath();c.roundRect(i*17+4,51,7,14,3);c.fill()}}
async function recordToggle(){const r=recording;if(!r||r.pending)return;if(r.active){stopRecording(r);return}if(r.blob&&!confirm('Die bisherige Aufnahme durch eine neue ersetzen?'))return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return toast('Audioaufnahme wird hier nicht unterstützt. Nutze bitte die Texteingabe.');r.pending=true;$('#recordButton').disabled=true;try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(r.disposed||r!==recording){stream.getTracks().forEach(t=>t.stop());return}r.stream=stream;if(r.url)URL.revokeObjectURL(r.url);r.blob=null;r.url=null;$('#audioResult').innerHTML='';let chunks=[];const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));r.recorder=new MediaRecorder(stream,type?{mimeType:type}:{});r.recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};r.recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());if(r.disposed)return;r.blob=new Blob(chunks,{type:r.recorder.mimeType});r.url=URL.createObjectURL(r.blob);if(r===recording&&$('#audioResult')){$('#audioResult').innerHTML=`<audio controls class="audio-player" src="${r.url}"></audio><a class="text-button" href="${r.url}" download="networkee-gespraech.${r.blob.type.includes('mp4')?'m4a':'webm'}">Aufnahme herunterladen</a><p class="sub">Audio wird nicht dauerhaft in der App gespeichert. Bei Bedarf jetzt herunterladen.</p>`;$('#recordButton').disabled=false;$('#recordStatus').textContent='Aufnahme bereit';}};r.recorder.onerror=()=>{stopRecording(r);toast('Aufnahme unterbrochen. Prüfe die Wiedergabe oder nutze Text.');};r.recorder.start();r.active=true;dirty=true;r.started=Date.now();$('#recordRing').classList.add('active');if(db.animations)$('#recordRing .mascot').classList.add('listening');$('#recordDot').className='red-dot';$('#recordStatus').textContent='Aufnahme läuft';$('#recordButton').innerHTML=svg('stop')+'Aufnahme beenden';$('#recordButton').disabled=false;$('#recordTime').textContent='00:00';r.timer=setInterval(()=>{if(r.disposed)return;const sec=Math.floor((Date.now()-r.started)/1000);if($('#recordTime'))$('#recordTime').textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');if(sec>=120)stopRecording(r)},250);try{r.ctx=new (window.AudioContext||window.webkitAudioContext)();await r.ctx.resume();const analyser=r.ctx.createAnalyser();analyser.fftSize=128;r.ctx.createMediaStreamSource(stream).connect(analyser);const data=new Uint8Array(analyser.frequencyBinCount);const animate=()=>{if(!r.active||!$('#wave'))return;analyser.getByteFrequencyData(data);const cv=$('#wave'),c=cv.getContext('2d');c.clearRect(0,0,660,116);c.fillStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent');for(let i=0;i<38;i++){const h=8+data[i]*.36;c.beginPath();c.roundRect(i*17+4,(116-h)/2,7,h,3);c.fill()}r.raf=requestAnimationFrame(animate)};animate()}catch{toast('Aufnahme läuft; Pegelanzeige ist in diesem Browser nicht verfügbar.')}}catch{r.stream?.getTracks().forEach(t=>t.stop());if($('#recordStatus'))$('#recordStatus').textContent='Mikrofon nicht verfügbar';toast('Mikrofonzugriff abgelehnt oder nicht verfügbar. Du kannst deine Notiz eintippen.');if($('#recordButton'))$('#recordButton').disabled=false}finally{r.pending=false}}
function stopRecording(r){if(!r||!r.active)return;r.active=false;clearInterval(r.timer);cancelAnimationFrame(r.raf);r.ctx?.close().catch(()=>{});if(r.recorder?.state==='recording')r.recorder.stop();if(r===recording&&$('#recordButton')){$('#recordRing').classList.remove('active');$('#recordRing .mascot').classList.remove('listening');$('#recordDot').className='';$('#recordStatus').textContent='Aufnahme wird vorbereitet';$('#recordButton').innerHTML=svg('mic')+'Neu aufnehmen';$('#recordButton').disabled=true;drawIdleWave()}}
function cleanupRecording(){const r=recording;if(!r)return;r.disposed=true;stopRecording(r);r.stream?.getTracks().forEach(t=>t.stop());clearInterval(r.timer);cancelAnimationFrame(r.raf);if(r.url)URL.revokeObjectURL(r.url);recording=null}
function reviewNote(){const r=recording;if(r?.active||r?.pending)return toast('Bitte zuerst die Aufnahme beenden.');const text=$('#noteText').value.trim(),contact=$('#noteContact').value;if(!text)return toast('Bitte eine Textnotiz ergänzen. Die Aufnahme wird noch nicht automatisch transkribiert.');if(r?.blob&&!confirm('Hast du die Aufnahme bei Bedarf heruntergeladen? Im nächsten Schritt wird nur die Textnotiz übernommen.'))return;dirty=false;cleanupRecording();if(!openModal(`<h1>So bleibt<br><span class="underline">nichts offen.</span></h1><div class="contact-chip">${avatar(person(contact))}<b>${esc(person(contact).name)}</b></div><form id="reviewForm"><label>Gesprächsnotiz</label><textarea name="text" required maxlength="12000">${esc(text)}</textarea><label>Nächster Schritt (optional)</label><input name="task" maxlength="200" placeholder="z. B. Angebot vorbereiten"><label>Fällig am</label><input name="date" type="date" value="${today()}"><p class="notice">Dein Text wird unverändert übernommen. Es findet noch keine KI-Auswertung statt.</p><button class="primary full">Bestätigen & speichern</button></form>`))return;dirty=true;$('#reviewForm').onsubmit=e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const v=Object.fromEntries(new FormData(e.target));if(!v.text.trim()||v.task.trim()&&!v.date){b.disabled=false;return toast('Bitte Notiz und bei einer Aufgabe das Datum ergänzen.')}if(change(()=>{person(contact).notes.push({id:uid(),text:v.text.trim(),date:today(),createdAt:new Date().toISOString()});if(v.task.trim())db.tasks.push({id:uid(),contact,title:v.task.trim(),date:v.date,done:false})},'Gespräch gespeichert. Dein nächster Schritt ist im Blick.'))closeModal(true);else b.disabled=false}}
function located(c){return c.lat!==''&&c.lng!==''&&c.lat!=null&&c.lng!=null&&Number.isFinite(+c.lat)&&Number.isFinite(+c.lng)&&Math.abs(+c.lat)<=90&&Math.abs(+c.lng)<=180}
function distance(a,b){const rad=x=>x*Math.PI/180,dlat=rad(b[0]-a[0]),dlon=rad(b[1]-a[1]);return 6371*2*Math.atan2(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dlon/2)**2),Math.sqrt(1-(Math.sin(dlat/2)**2+Math.cos(rad(a[0]))*Math.cos(rad(b[0]))*Math.sin(dlon/2)**2)))}
let radius=50;
function mapContacts(){return db.contacts.filter(located).filter(c=>mapMode!=='Nähe'||(nearOrigin&&distance(nearOrigin,[+c.lat,+c.lng])<=radius))}
function network(){mapList=mapContacts();const total=db.contacts.filter(located),countries=new Set(total.map(c=>(c.country||'').trim().toLowerCase()).filter(Boolean));return `${heading('Dein Netzwerk.<br><span class="underline">Überall.</span>',false)}<div class="filters">${['Netzwerk','Welt','Schweiz','Nähe'].map(m=>`<button class="${m===mapMode?'active':''}" onclick="setMapMode('${m}')">${m==='Nähe'?'In meiner Nähe':m==='Netzwerk'?'Mein Netzwerk':m}</button>`).join('')}</div>${mapMode==='Nähe'?`<div class="notice">${nearOrigin?'Ausgangspunkt gewählt.':'Wähle einen Ausgangspunkt, um Kontakte in der Nähe zu finden.'}<div class="actions"><button class="secondary" onclick="locateMe()">Mein Standort</button><button class="secondary" onclick="manualOrigin()">Ort auf Karte wählen</button></div><label>Umkreis</label><select onchange="radius=+this.value;render()">${[10,25,50,100,250,500].map(r=>`<option value="${r}" ${radius===r?'selected':''}>${r} km</option>`).join('')}</select></div>`:''}${mapAllowed?`<div class="mapbox" id="worldmap"></div><p id="mapStatus" class="sub"></p><div class="map-summary warm-panel">${svg('globe')} ${mapList.length} Kontakte mit Standort · ${countries.size} hinterlegte Länder</div><div id="mapSelected" class="mapselected"></div>`:`<div class="warm-panel" style="padding:25px"><h2>Wo sind deine Kontakte zuhause?</h2>${mapConsent()}<button class="primary" onclick="mapAllowed=true;render()">Karte aktivieren</button></div>`}<div class="section-head"><h2>${mapMode==='Nähe'?'Kontakte im Umkreis':'Deine Standorte'}</h2><button class="text-button" onclick="locationManager()">Standorte prüfen</button></div>${(mapMode==='Nähe'?mapList:db.contacts).map(c=>`<button class="row" onclick="${located(c)?`selectMapContact('${c.id}')`:`locationResolve('${c.id}')`}">${avatar(c)}<span class="body"><h3>${esc(c.name)}</h3><p>${esc(c.location||'Ort fehlt')}${located(c)?'':' · Ort noch nicht auf der Karte'}</p></span>${svg('chevron')}</button>`).join('')||'<div class="empty"><h3>Hier ist noch niemand verzeichnet.</h3><p>Erweitere den Umkreis oder ergänze Standorte bei deinen Kontakten.</p></div>'}`}
function mapConsent(){return '<p class="sub">Die Karte lädt Inhalte von OpenStreetMap und unpkg. IP-Adresse und Kartenausschnitt werden an externe Anbieter übertragen. Kontaktnamen, Fotos und Notizen werden nicht an diese Anbieter gesendet.</p>'}
function leaflet(){if(window.L)return Promise.resolve();if(mapLoading)return mapLoading;mapLoading=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const js=document.createElement('script');js.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';js.onload=()=>resolve();js.onerror=()=>{mapLoading=null;reject(Error('Karte nicht verfügbar'))};document.head.append(js)});return mapLoading}
function tiles(map,status){let errors=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).on('tileerror',()=>{if(++errors===3&&status)status.textContent='Kartenteile konnten nicht geladen werden. Die Kontaktliste bleibt verfügbar.'}).addTo(map)}
function setMapMode(m){mapMode=m;render()}
async function loadMap(){try{await leaflet();if(page!=='Netzwerk'||!$('#worldmap'))return;mapObj=L.map('worldmap',{worldCopyJump:true}).setView(mapMode==='Schweiz'?[46.8,8.2]:mapMode==='Nähe'&&nearOrigin?nearOrigin:[22,0],mapMode==='Schweiz'?7:mapMode==='Nähe'&&nearOrigin?8:2);tiles(mapObj,$('#mapStatus'));if(mapMode==='Netzwerk'&&mapList.length)mapObj.fitBounds(mapList.map(c=>[+c.lat,+c.lng]),{padding:[45,45],maxZoom:9});const layer=L.layerGroup().addTo(mapObj);const markers=()=>{layer.clearLayers();const groups=[];for(const c of mapList){const pt=mapObj.latLngToLayerPoint([+c.lat,+c.lng]);let g=groups.find(g=>g.p.distanceTo(pt)<42);if(g)g.people.push(c);else groups.push({p:pt,people:[c]})}for(const g of groups){const c=g.people[0];const html=g.people.length>1?String(g.people.length):safePhoto(c.photo)?`<img src="${c.photo}" alt="">`:esc(initials(c.name));const m=L.marker([+c.lat,+c.lng],{icon:L.divIcon({className:'mapmarker',html,iconSize:[40,40],iconAnchor:[20,20]})}).addTo(layer);m.on('click',()=>{if(g.people.length===1)selectMapContact(c.id);else{const box=document.createElement('div');g.people.forEach(x=>{const b=document.createElement('button');b.textContent=x.name;b.style.display='block';b.style.padding='8px';b.onclick=()=>selectMapContact(x.id);box.append(b)});m.bindPopup(box).openPopup()}})}};markers();mapObj.on('zoomend',markers);if(mapMode==='Nähe'&&nearOrigin)L.circle(nearOrigin,{radius:radius*1000,color:'#5475cf',fillOpacity:.04}).addTo(mapObj);$('#mapStatus').textContent='Marker öffnen Kontakte. Zahlen bündeln nahe beieinanderliegende Standorte.';if(mapSelected&&person(mapSelected))showMapSelected(mapSelected)}catch{if($('#mapStatus'))$('#mapStatus').textContent='Karte derzeit nicht erreichbar. Nutze die Kontaktliste darunter.'}}
function showMapSelected(id){const c=person(id);if(!c||!$('#mapSelected'))return;$('#mapSelected').innerHTML=`<article class="card"><div class="row">${avatar(c)}<div class="body"><h3>${esc(c.name)}</h3><p>${esc(c.company)}</p><p class="muted">${esc(c.location)}</p></div><div class="actions"><button class="secondary" onclick="detail('${id}')">Kontakt öffnen</button><button class="text-button" onclick="locationResolve('${id}')">Standort prüfen</button></div></div></article>`}
function selectMapContact(id){mapSelected=id;const c=person(id);if(!mapObj)return detail(id);mapObj.setView([+c.lat,+c.lng],Math.max(mapObj.getZoom(),8));showMapSelected(id);$('#mapSelected').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}
function locateMe(){if(!navigator.geolocation)return toast('Standort nicht verfügbar. Wähle den Ort auf der Karte.');toast('Standort wird ermittelt …');navigator.geolocation.getCurrentPosition(p=>{nearOrigin=[p.coords.latitude,p.coords.longitude];render()},()=>toast('Standortzugriff nicht möglich. Wähle den Ort manuell auf der Karte.'),{timeout:10000,maximumAge:60000})}
function manualOrigin(){if(!mapAllowed){toast('Bitte zuerst die Karte aktivieren.');return}if(!openModal('<h1>Dein Ausgangspunkt</h1><p>Klicke auf den gewünschten Ort. Er wird nur für die aktuelle Sitzung verwendet.</p><div id="originMap" class="mapbox"></div><p id="originStatus" class="sub">Noch kein Punkt gewählt.</p><button class="primary full" id="originSave" disabled>Umkreis anzeigen</button>'))return;leaflet().then(()=>{if(!$('#originMap'))return;picker=L.map('originMap').setView(nearOrigin||[46.8,8.2],5);tiles(picker);let chosen=null,mark;picker.on('click',e=>{chosen=[e.latlng.lat,((e.latlng.lng+180)%360+360)%360-180];if(mark)mark.setLatLng(chosen);else mark=L.marker(chosen).addTo(picker);$('#originStatus').textContent='Ausgangspunkt gewählt.';$('#originSave').disabled=false});$('#originSave').onclick=()=>{nearOrigin=chosen;closeModal(true);render()}}).catch(()=>toast('Karte nicht erreichbar.'))}
async function pickLocation(){if(!mapAllowed){$('#picker').innerHTML=mapConsent()+'<button type="button" class="secondary" onclick="mapAllowed=true;pickLocation()">Karte aktivieren</button>';return}picker?.remove();$('#picker').innerHTML='<p class="sub">Zoome zum Ort und klicke auf die Karte. Ort und Land bitte zusätzlich eintragen.</p><div id="pickmap" class="mapbox"></div>';try{await leaflet();if(!$('#pickmap'))return;const a=$('#cf [name=lat]'),b=$('#cf [name=lng]');picker=L.map('pickmap').setView(a.value!==''&&b.value!==''?[+a.value,+b.value]:[46.8,8.2],a.value!==''?8:4);tiles(picker);let mark;if(a.value!==''&&b.value!=='')mark=L.marker([+a.value,+b.value]).addTo(picker);picker.on('click',e=>{a.value=e.latlng.lat.toFixed(5);b.value=(((e.latlng.lng+180)%360+360)%360-180).toFixed(5);if(mark)mark.setLatLng([+a.value,+b.value]);else mark=L.marker([+a.value,+b.value]).addTo(picker);$('#locationStatus').textContent='Standort gewählt. Kontakt speichern, um ihn zu übernehmen.';dirty=true})}catch{$('#picker').innerHTML='<p class="notice">Karte nicht erreichbar. Koordinaten lassen sich manuell eingeben.</p>'}}
function privacy(){openModal(`<h1>Deine Daten.<br>Deine Entscheidung.</h1><p>Kontakte, Notizen, Chancen, Profilbilder und Einstellungen werden ausschliesslich im Browser-Speicher dieses Geräts abgelegt. Es gibt noch kein Cloud-Konto und keine Synchronisierung.</p><p>Audio bleibt bis zum Schliessen der Aufnahmeansicht im Arbeitsspeicher. Es wird nicht an einen KI-Dienst geschickt und nicht dauerhaft gespeichert. Du kannst es herunterladen.</p><p>Die Karte nutzt nach Zustimmung externe Kartenanbieter. Die Ortssuche übermittelt nach Klick auf „Ort suchen“ ausschliesslich Stadt und Land an Open-Meteo; keine Namen, Notizen oder Kontaktdaten. Die Standortfreigabe für „In meiner Nähe“ wird nur auf deinen Wunsch angefragt.</p><p class="notice">Nutze für diesen Prototyp Beispieldaten. Browserdaten können verloren gehen. Der Export enthält alle lokalen CRM-Daten, aber keine Audioaufnahmen.</p><div class="actions"><button class="primary" onclick="exportData()">Daten exportieren</button><button class="secondary" onclick="mapAllowed=false;closeModal(true);render();toast('Kartenfreigabe für diese Sitzung zurückgenommen')">Kartenfreigabe zurücknehmen</button></div><button class="text-button full" onclick="resetDemo()">Beispieldaten neu laden</button><button class="text-button danger full" onclick="clearData()">Alle lokalen App-Daten löschen</button>`)}
function exportData(){const url=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='networkee-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function resetDemo(){if(!confirm('Alle lokalen Eingaben durch Beispieldaten ersetzen? Vorher bei Bedarf exportieren.'))return;if(change(()=>db=seed(),'Beispieldaten geladen'))closeModal(true)}
function clearData(){if(!confirm('Alle lokalen Kontakte, Notizen, Aufgaben, Chancen und Profilangaben löschen?'))return;if(change(()=>db={profile:{name:'',company:'',photo:''},theme:'Blau',animations:true,contacts:[],tasks:[],deals:[]},'Lokale App-Daten gelöscht'))closeModal(true)}
function help(){openModal(`<h1>Einfach anfangen.</h1><h3>1. Menschen hinzufügen</h3><p>Lege einen Kontakt mit Unternehmen, Typ und optional einem Standort an.</p><h3>2. Gespräche festhalten</h3><p>Tippe deine Notiz ein oder nutze die lokale Audioaufnahme als Gedächtnisstütze. Transkription und KI sind noch nicht angeschlossen.</p><h3>3. Dranbleiben</h3><p>Erstelle einen nächsten Schritt mit Termin. Fällige Aufgaben erscheinen auf deiner Startseite.</p><h3>Feedback</h3><p>Teile deine Beobachtungen mit Francesco, zum Beispiel mit einem Screenshot und den Schritten zum Problem. In diesem Prototyp wird kein Feedback automatisch verschickt.</p><p class="notice">Version 0.4 · Nutzenpilot. Registrierung, Cloud-Speicherung, KI, externe Benachrichtigungen und Abonnement folgen später.</p>`)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#modal').innerHTML){const a=$$('#modal button:not([disabled]),#modal input,#modal select,#modal textarea,#modal a[href]').filter(n=>n.getClientRects().length);if(!a.length)return;const first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('beforeunload',e=>{if(dirty||recording?.active||recording?.blob){e.preventDefault();e.returnValue=''}});
render();

let geoResults=[],geoRequest=0;
const geoCache=new Map();
function locationTextChanged(){const f=$('#cf');if(!f)return;f.querySelector('[name=lat]').value='';f.querySelector('[name=lng]').value='';$('#locationStatus').textContent='Ort geändert. Nach dem Speichern bitte den neuen Kartenpunkt bestätigen.';dirty=true}
function locationManager(){openModal(`<h1>Dein Netzwerk verorten.</h1><p>Ein Ortsname braucht einen Kartenpunkt. Prüfe auch ältere Einträge, wenn ein Marker nicht zum angegebenen Ort passt.</p>${db.contacts.map(c=>`<button class="row" onclick="locationResolve('${c.id}')">${avatar(c)}<span class="body"><h3>${esc(c.name)}</h3><p>${esc(c.location||'Ort fehlt')}${c.country?' · '+esc(c.country):''}</p><span class="sub">${located(c)?'Kartenpunkt vorhanden':'Noch nicht auf der Karte'}</span></span><b>Prüfen</b></button>`).join('')||'<p>Noch keine Kontakte.</p>'}`,{wide:true})}
function locationResolve(id){const c=person(id);if(!c)return;geoRequest++;geoResults=[];openModal(`<h1>Wo ist ${esc(c.name.split(' ')[0])}<br>zuhause?</h1><p>Wähle den passenden Ort. Der Kartenpunkt zeigt das Ortszentrum, keine genaue Adresse.</p><label for="geoCity">Stadt / Ort</label><input id="geoCity" value="${esc((c.location||'').split(',')[0])}" placeholder="z. B. Zürich"><label for="geoCountry">Land (optional)</label><input id="geoCountry" value="${esc(c.country||(c.location||'').split(',')[1]?.trim()||'')}" placeholder="z. B. Schweiz"><p class="notice">Mit „Ort suchen“ werden Stadt und Land an Open-Meteo gesendet. Keine Kontaktnamen oder Notizen.</p><button class="primary full" id="geoSearch" onclick="searchLocation('${id}')">${svg('search')}Ort suchen</button><div id="geoResults" aria-live="polite"></div><p class="sub">Ortsdaten: <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a> / <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a></p><button class="text-button full" onclick="contactForm('${id}')">Kontakt bearbeiten / Punkt manuell wählen</button>`,{wide:true})}
async function searchLocation(id){const city=$('#geoCity')?.value.trim(),country=$('#geoCountry')?.value.trim();if(!city||city.length<2)return toast('Bitte einen Ortsnamen mit mindestens zwei Zeichen eingeben.');const query=city+(country?', '+country:''),request=++geoRequest,button=$('#geoSearch'),result=$('#geoResults');button.disabled=true;result.innerHTML='<p class="notice">Passende Orte werden gesucht …</p>';try{let items=geoCache.get(query.toLowerCase());if(!items){const u=new URL('https://geocoding-api.open-meteo.com/v1/search');u.search=new URLSearchParams({name:query,count:'8',language:'de',format:'json'});const response=await fetch(u,{signal:AbortSignal.timeout(12000),credentials:'omit',referrerPolicy:'no-referrer'});if(!response.ok)throw Error('unavailable');const data=await response.json();items=(data.results||[]).filter(x=>Number.isFinite(x.latitude)&&Number.isFinite(x.longitude));geoCache.set(query.toLowerCase(),items)}if(request!==geoRequest||!result.isConnected)return;geoResults=items;result.innerHTML=items.length?'<h2 style="margin-top:20px">Welchen Ort meinst du?</h2>'+items.map((x,i)=>`<button class="row geo-result" onclick="chooseLocation('${id}',${i})"><span class="body"><h3>${esc(x.name)}</h3><p>${esc([x.admin1,x.country].filter(Boolean).join(' · '))}</p></span><b>Übernehmen</b></button>`).join(''):'<p class="notice">Kein passender Ort gefunden. Prüfe die Schreibweise oder suche nur nach dem Ortsnamen. Du kannst den Punkt auch manuell wählen.</p>'}catch{if(request===geoRequest&&result.isConnected)result.innerHTML='<p class="notice">Die Ortssuche ist gerade nicht erreichbar. Versuche es erneut oder wähle den Punkt manuell. Deine gespeicherten Kontaktdaten bleiben erhalten.</p>'}finally{if(button.isConnected)button.disabled=false}}
function chooseLocation(id,index){const x=geoResults[index],c=person(id);if(!x||!c)return;if(change(()=>Object.assign(c,{location:x.name,country:x.country||'',countryCode:x.country_code||'',lat:x.latitude,lng:x.longitude,locationSource:'Open-Meteo / GeoNames'}),'Standort bestätigt und auf der Karte hinterlegt.')){closeModal(true);page='Netzwerk';mapMode='Netzwerk';mapSelected=id;render()}}
